//! 🗜️ Original compressed bytes produce paid pages while codec and output custody close independently.
use semio_framework_value_native_owned::native_decoding::NativeDecodeCloseControl;
use protocol::codec::{DeflateRetainedCursor,DeflateRetainedStep,RetainedInflateCloseStep,OriginalWireSourceIdentity,RetainedWireByteSource,PackRefusal};
use semio_framework_value::{RetainedCloneGrant, RetainedCloneProgress, RetirementDemand, ValueError, ValueRefusalKind};
use semio_framework_value_native_owned::native_decoding::NativeDecodeControl;
use semio_framework_value_persistent::list::PagedList;
use std::mem::ManuallyDrop;

pub struct RetainedHistoryDeflatePayload{original:OriginalWireSourceIdentity,range:(usize,usize),pages:ManuallyDrop<PagedList<u8,{usize::MAX}>>}
impl RetainedHistoryDeflatePayload{
 pub fn compressed_source_identity(&self)->OriginalWireSourceIdentity{self.original}
 pub fn original_range(&self)->(usize,usize){self.range}
 pub fn allocated_bytes(&self)->usize{self.pages.allocated_bytes()}
 pub fn close_demands(&self)->Result<RetirementDemand,PackRefusal>{if !self.pages.is_empty(){return Ok(RetirementDemand{depth:self.pages.next_pop_depth_demand().map_err(page_fault)?,..Default::default()})}Ok(RetirementDemand{release_bytes:self.pages.next_release_allocation_bytes().map_err(page_fault)?,depth:self.pages.next_release_depth_demand().map_err(page_fault)?,..Default::default()})}
 pub fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneProgress,PackRefusal>{let d=self.close_demands()?;if !permits(g,d){return Ok(Default::default())}if self.pages.pop().is_some(){return Ok(metadata())}if self.pages.terminal_is_empty(){return Ok(Default::default())}let p=self.pages.release_empty_page(g.maximum_release_bytes).map_err(page_fault)?;Ok(RetainedCloneProgress{released_bytes:p.released_allocation_bytes,..metadata()})}
 pub fn terminal_is_empty(&self)->bool{self.pages.terminal_is_empty()}
}
impl RetainedWireByteSource for RetainedHistoryDeflatePayload{
 fn original_source_identity(&self)->OriginalWireSourceIdentity{OriginalWireSourceIdentity{range_start:0,address:self.pages.backing_ptr(0).map_or(0,|pointer|pointer as usize),extent:self.pages.len(),authority:self.original.authority}}
 fn byte_at(&self,index:usize)->Option<u8>{self.pages.get(index).copied()}
}
impl Drop for RetainedHistoryDeflatePayload{fn drop(&mut self){assert!(self.terminal_is_empty()||std::thread::panicking(),"original Deflate payload abandoned paid pages");if self.terminal_is_empty(){unsafe{ManuallyDrop::drop(&mut self.pages)}}}}

#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub enum RetainedHistoryDeflateStep{Blocked,Progress,Ready,Closed}
pub struct RetainedHistoryDeflateDecode{source:OriginalWireSourceIdentity,control:(u64,Option<u64>),range:(usize,usize),position:usize,expected:usize,complete:bool,closing:bool,closed:bool,codec:ManuallyDrop<Option<DeflateRetainedCursor>>,payload:ManuallyDrop<Option<RetainedHistoryDeflatePayload>>,receipt:Option<(RetainedCloneGrant,RetainedCloneProgress)>}
fn fault(reason:&'static str)->PackRefusal{ValueError::literal(ValueRefusalKind::InvalidValue,reason).into()}
fn page_fault(error:semio_framework_value_persistent::list::PagedListError)->PackRefusal{PackRefusal::from_paged_refusal(error,"original History Deflate pages",0)}
fn permits(g:RetainedCloneGrant,d:RetirementDemand)->bool{g.maximum_items>0&&g.maximum_depth>=d.depth&&g.maximum_copy_bytes>=d.copy_bytes&&g.maximum_capacity_bytes>=d.capacity_bytes&&g.maximum_release_bytes>=d.release_bytes}
fn metadata()->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,..Default::default()}}
impl RetainedHistoryDeflateDecode{
 pub fn admit<S:RetainedWireByteSource+?Sized>(source:&S,range:(usize,usize),expected:usize,maximum_frame_bytes:usize,control:&NativeDecodeControl<'_>,g:RetainedCloneGrant)->Result<Option<Self>,PackRefusal>{let identity=source.original_source_identity();if range.0>range.1||range.1>identity.extent||range.1-range.0>maximum_frame_bytes||expected>maximum_frame_bytes{return Err(fault("original compressed History range exceeds declared frame policy"))}if g.maximum_items==0||g.maximum_depth<2{return Ok(None)}let codec=DeflateRetainedCursor::try_new(expected as u64,maximum_frame_bytes as u64,control.maximum_bytes())?;Ok(Some(Self{source:identity,control:(control.ledger_identity(),control.retirement_recipient_identity()),range,position:range.0,expected,complete:false,closing:false,closed:false,codec:ManuallyDrop::new(Some(codec)),payload:ManuallyDrop::new(Some(RetainedHistoryDeflatePayload{original:identity,range,pages:ManuallyDrop::new(PagedList::empty())})),receipt:Some((g,metadata()))}))}
 fn validate<S:RetainedWireByteSource+?Sized>(&self,source:&S,control:&dyn NativeDecodeCloseControl)->Result<(),PackRefusal>{if self.source!=source.original_source_identity()||self.control!=(control.ledger_identity(),control.retirement_recipient_identity()){return Err(fault("original compressed History changed source or receiving owner"))}Ok(())}
 fn publish(&mut self,g:RetainedCloneGrant,p:RetainedCloneProgress)->Result<(),PackRefusal>{self.receipt=Some((g,p));if !p.fits(g){return Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"original compressed History exceeded supplied grant").with_retained_progress(p).into())}Ok(())}
 pub fn take_receipt(&mut self)->Option<(RetainedCloneGrant,RetainedCloneProgress)>{self.receipt.take()}
 pub fn receipt(&self)->Option<(RetainedCloneGrant,RetainedCloneProgress)>{self.receipt}
 pub fn consumed_end(&self)->usize{self.position}
 pub fn produced_bytes(&self)->usize{self.payload.as_ref().map_or(0,|payload|payload.pages.len())}
 pub fn is_ready(&self)->bool{self.complete&&!self.closing&&!self.closed&&self.receipt.is_none()&&self.payload.is_some()}
 pub fn demands<S:RetainedWireByteSource+?Sized>(&self,source:&S,control:&dyn NativeDecodeCloseControl)->Result<RetirementDemand,PackRefusal>{self.validate(source,control)?;if self.receipt.is_some()||self.closed{return Ok(Default::default())}let Some(codec)=self.codec.as_ref()else{return Ok(RetirementDemand{depth:1,..Default::default()})};if self.closing{let mut d=codec.retirement_demands();d.depth+=1;return Ok(d)}if let Some(bytes)=codec.next_allocation_bytes(){return Ok(RetirementDemand{capacity_bytes:bytes,depth:2,..Default::default()})}let pages=&self.payload.as_ref().unwrap().pages;if !pages.has_reserved_slot()&&pages.len()<self.expected{return Ok(RetirementDemand{copy_bytes:pages.next_reserve_copy_byte_demand().map_err(page_fault)?,capacity_bytes:pages.next_allocation_bytes().map_err(page_fault)?,depth:pages.next_reserve_depth_demand().map_err(page_fault)?+1,..Default::default()})}Ok(RetirementDemand{copy_bytes:if codec.can_admit()&&self.position<self.range.1{1}else{2},depth:2,..Default::default()})}
 pub fn step<S:RetainedWireByteSource+?Sized>(&mut self,source:&S,control:&mut NativeDecodeControl<'_>,g:RetainedCloneGrant)->Result<RetainedHistoryDeflateStep,PackRefusal>{self.validate(source,control)?;if self.receipt.is_some()||self.closed||self.closing{return Ok(RetainedHistoryDeflateStep::Blocked)}if self.is_ready(){return Ok(RetainedHistoryDeflateStep::Ready)}let d=self.demands(source,control)?;if !permits(g,d){return Ok(RetainedHistoryDeflateStep::Blocked)}control.checkpoint()?;control.charge(d.capacity_bytes)?;let result=self.step_inner(source,g);if result.is_err(){self.closing=true}result}
 fn step_inner<S:RetainedWireByteSource+?Sized>(&mut self,source:&S,g:RetainedCloneGrant)->Result<RetainedHistoryDeflateStep,PackRefusal>{let codec=self.codec.as_mut().unwrap();if codec.next_allocation_bytes().is_some(){let result=codec.reserve_allocation(g.maximum_capacity_bytes);let p=match result{Ok(step)=>RetainedCloneProgress{retained_capacity_bytes:step.allocated_bytes,..metadata()},Err(error)=>{let p=RetainedCloneProgress{retained_capacity_bytes:error.allocated_bytes,..metadata()};self.publish(g,p)?;return Err(PackRefusal::RetainedAllocation{kind:error.kind,allocated_bytes:error.allocated_bytes,what:"original History Deflate window",offset:self.position as u64,detail:error.reason})}};self.publish(g,p)?;return Ok(RetainedHistoryDeflateStep::Progress)}let pages=&mut self.payload.as_mut().unwrap().pages;if !pages.has_reserved_slot()&&pages.len()<self.expected{let result=pages.reserve_one_funded(RetainedCloneGrant{maximum_depth:g.maximum_depth-1,..g});let p=match result{Ok(p)=>p,Err(error)=>{self.publish(g,RetainedCloneProgress{retained_capacity_bytes:error.allocated_bytes,..metadata()})?;return Err(PackRefusal::from_paged_allocation(error,"original History Deflate pages",self.position as u64))}};self.publish(g,p)?;return Ok(RetainedHistoryDeflateStep::Progress)}if codec.can_admit()&&self.position<self.range.1{let byte=source.byte_at(self.position).ok_or_else(||fault("original compressed History source byte is absent"))?;codec.admit_byte(byte).map_err(|_|fault("original compressed History codec rejected admitted byte"))?;self.position+=1;self.publish(g,RetainedCloneProgress{copied_bytes:1,..metadata()})?;return Ok(RetainedHistoryDeflateStep::Progress)}let result=codec.grant(self.position==self.range.1);let mut p=metadata();match result{Ok(DeflateRetainedStep::Byte(byte))=>{if pages.push_reserved(byte).is_err(){p.copied_bytes=1;self.publish(g,p)?;return Err(fault("original History Deflate output lost its funded slot"))}p.copied_bytes=2},Ok(DeflateRetainedStep::Complete)=>{if self.position!=self.range.1||pages.len()!=self.expected{self.publish(g,p)?;return Err(fault("original History Deflate has trailing input or incorrect decoded length"))}self.complete=true},Ok(DeflateRetainedStep::NeedInput)=>{},Err(error)=>{self.publish(g,p)?;return Err(error)}}self.publish(g,p)?;Ok(RetainedHistoryDeflateStep::Progress)}
 pub fn cancel(&mut self){self.closing=true}
 pub fn take_ready_into(&mut self,recipient:&mut Option<RetainedHistoryDeflatePayload>,g:RetainedCloneGrant)->Result<bool,PackRefusal>{if !self.is_ready(){return Ok(false)}self.take_payload_into(recipient,g)}
 pub fn take_partial_into(&mut self,recipient:&mut Option<RetainedHistoryDeflatePayload>,g:RetainedCloneGrant)->Result<bool,PackRefusal>{if !self.closing||self.receipt.is_some(){return Ok(false)}self.take_payload_into(recipient,g)}
 fn take_payload_into(&mut self,recipient:&mut Option<RetainedHistoryDeflatePayload>,g:RetainedCloneGrant)->Result<bool,PackRefusal>{if self.payload.is_none()||recipient.is_some()||g.maximum_items==0||g.maximum_depth<1{return Ok(false)}*recipient=self.payload.take();self.closing=true;self.publish(g,metadata())?;Ok(true)}
 pub fn close_step<S:RetainedWireByteSource+?Sized>(&mut self,source:&S,control:&dyn NativeDecodeCloseControl,g:RetainedCloneGrant)->Result<RetainedHistoryDeflateStep,PackRefusal>{self.validate(source,control)?;if !self.closing||self.closed||self.receipt.is_some(){return Ok(RetainedHistoryDeflateStep::Blocked)}if !permits(g,self.demands(source,control)?){return Ok(RetainedHistoryDeflateStep::Blocked)}if let Some(codec)=self.codec.as_mut(){if codec.terminal_is_empty(){drop(self.codec.take());self.publish(g,metadata())?;return Ok(RetainedHistoryDeflateStep::Progress)}let step=codec.close_step(g.maximum_items,g.maximum_release_bytes);let p=match step{RetainedInflateCloseStep::Complete=>metadata(),RetainedInflateCloseStep::Pending{released_items,released_bytes}=>RetainedCloneProgress{copied_items:released_items,released_bytes,..Default::default()}};self.publish(g,p)?;return Ok(RetainedHistoryDeflateStep::Progress)}if self.payload.is_some(){return Ok(RetainedHistoryDeflateStep::Blocked)}self.closed=true;self.publish(g,metadata())?;Ok(RetainedHistoryDeflateStep::Closed)}
 pub fn terminal_is_empty(&self)->bool{self.closed&&self.codec.is_none()&&self.payload.is_none()&&self.receipt.is_none()}
}
impl Drop for RetainedHistoryDeflateDecode{fn drop(&mut self){assert!(self.terminal_is_empty()||std::thread::panicking(),"original History Deflate abandoned codec or output custody");if self.terminal_is_empty(){unsafe{ManuallyDrop::drop(&mut self.codec);ManuallyDrop::drop(&mut self.payload)}}}}
